head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > setCellClass]<br/>Calendar 컴포넌트의 특정 날짜에 CSS 클래스를 설정합니다.",
    "validation" : [
        "date(필수) 파라미터로 CSS 클래스를 설정할 날짜를 'yyyyMMdd' 포맷 문자열로 설정합니다.",
        "className(필수) 파라미터로 설정할 CSS 클래스명을 String 으로 설정합니다.",
        "className 파라미터는 공백으로 구분하여 여러 클래스를 동시에 설정할 수 있습니다.",
        "동일 날짜에 setCellClass() 메소드를 다시 실행하면 이전에 설정된 클래스가 새 클래스로 덮어씌워집니다.",
        "비활성화된 날짜(w2calendar_date_disable)에는 클래스가 적용되지 않습니다.",
        "설정된 CSS 클래스는 현재 표시된 월의 활성화 된 날짜에만 적용됩니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // comp 생성 함수 호출 (createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 표시월: 2025-11)
    await $c.gcm.createBasicCalendar();
}



// setCellClass 호출 (선택된 케이스에 따라 분기)
// validation:
//  - date: 'yyyyMMdd' 포맷 String
//  - className: String, 공백 구분 시 여러 클래스 동시 설정
//  - 동일 날짜 재호출 시 이전 클래스가 새 클래스로 덮어씌워짐
//  - 비활성화 날짜(w2calendar_date_disable)에는 적용되지 않음
//  - 현재 표시된 월의 활성화 된 날짜에만 적용됨
scwin.btn_setCellClass_onclick = function (e) {
    let caseId = con_gotoCase.getValue();
    let targetDate = "";
    let appliedClass = "";

    if (caseId === '1') {
        // 케이스 1: 기본 설정 - 2025-11-15 에 'tmpColor01' 클래스 설정
        targetDate = "20251115";
        target1.setCellClass("20251115", "tmpColor01");
        appliedClass = "tmpColor01";
    } else if (caseId === '2') {
        // 케이스 2: className 공백 구분으로 여러 클래스 동시 설정
        targetDate = "20251120";
        target1.setCellClass("20251120", "tmpColor01 tmpColor02");
        appliedClass = "tmpColor01 tmpColor02";
    } else if (caseId === '3') {
        // 케이스 3: 동일 날짜에 재호출 → 새 클래스로 덮어씌워짐
        targetDate = "20251115";
        target1.setCellClass("20251115", "tmpColor01");
        target1.setCellClass("20251115", "tmpColor02");
        appliedClass = "tmpColor02 (tmpColor01 → tmpColor02 덮어씀)";
    } else if (caseId === '4') {
        // 케이스 4: 비활성화 날짜에는 클래스가 적용되지 않음
        // 사전 셋업: setDisableBeforeDate('20251110') → 2025-11-10 이전 비활성화
        // 2025-11-05 셀에 클래스 설정 시도 (비활성화 상태)
        target1.setDisableBeforeDate("20251110");
        targetDate = "20251105";
        target1.setCellClass("20251105", "tmpColor01");
        appliedClass = "tmpColor01 (비활성화 날짜)";
    }

    // 설정 후 해당 날짜 셀의 className 확인
    let cellClassName = scwin.fn_getCellClass(targetDate);

    wf_body_bottom.getObj("scwin").setReturnValue(
        "[setCellClass 호출 인자] date='" + targetDate + "', className='" + appliedClass + "'"
    );
    wf_body_bottom.getObj("scwin").setReturnValue(
        "[target 날짜 셀 className] " + cellClassName
    );
};



// 지정 yyyyMMdd 날짜에 해당하는 셀의 className 조회
// 현재 표시된 월의 활성화 된 날짜 셀은 w2calendar_date_on 클래스 + w2calendar_date_{일자} 클래스를 가짐
// 비활성화 날짜는 w2calendar_date_disable 클래스를 가짐
scwin.fn_getCellClass = function (yyyyMMdd) {
    // 표시 중인 캘린더의 표시월 추출 (selectedDateHelper 기반)
    let displayedYear = String(target1.selectedDateHelper.getYear());
    let displayedMonth = String(target1.selectedDateHelper.getMonth()).padStart(2, '0');
    let yyyy = yyyyMMdd.substring(0, 4);
    let mm = yyyyMMdd.substring(4, 6);
    let dd = yyyyMMdd.substring(6, 8);

    // w2calendar_date_{dd} 클래스를 가진 셀 조회 (일자 숫자, padding 없음 - 예: 5, 15)
    let dayNum = parseInt(dd, 10);
    let cells = target1.render.querySelectorAll('td.w2calendar_date_' + dayNum);

    if (cells.length === 0) {
        return "(해당 날짜 셀 없음)";
    }

    // 현재 표시월 내 첫 번째 매칭 셀 반환
    return cells[0].className;
};
